INSERT INTO subjects(code,name) SELECT 'DEMO-DBMS','Database Management Systems' WHERE NOT EXISTS (SELECT 1 FROM subjects WHERE code='DEMO-DBMS');
INSERT INTO subjects(code,name) SELECT 'DEMO-DSA','Data Structures & Algorithms' WHERE NOT EXISTS (SELECT 1 FROM subjects WHERE code='DEMO-DSA');
INSERT INTO subjects(code,name) SELECT 'DEMO-OS','Operating Systems' WHERE NOT EXISTS (SELECT 1 FROM subjects WHERE code='DEMO-OS');
INSERT INTO subjects(code,name) SELECT 'DEMO-CN','Computer Networks' WHERE NOT EXISTS (SELECT 1 FROM subjects WHERE code='DEMO-CN');
INSERT INTO subjects(code,name) SELECT 'DEMO-MATH','Discrete Mathematics' WHERE NOT EXISTS (SELECT 1 FROM subjects WHERE code='DEMO-MATH');
INSERT INTO enrollments(student_id,subject_id) SELECT s.id,sub.id FROM students s CROSS JOIN subjects sub WHERE s.roll_no REGEXP '^DEMO00[1-9]$|^DEMO01[0-5]$' AND sub.code IN ('DEMO-DBMS','DEMO-DSA','DEMO-OS','DEMO-CN','DEMO-MATH') AND NOT EXISTS (SELECT 1 FROM enrollments e WHERE e.student_id=s.id AND e.subject_id=sub.id);
INSERT INTO class_sessions(subject_id,session_date,period_no) SELECT id,'2026-10-12',1 FROM subjects WHERE code='DEMO-DBMS' AND NOT EXISTS (SELECT 1 FROM class_sessions cs WHERE cs.subject_id=subjects.id AND cs.session_date='2026-10-12' AND cs.period_no=1);
INSERT INTO attendance(session_id,student_id,status) SELECT @sid,e.student_id,IF(MOD(e.student_id+1,5)=0 OR (MOD(e.student_id,7)=0 AND 1<4),'Absent','Present') FROM enrollments e JOIN subjects sub ON sub.id=e.subject_id WHERE sub.code='DEMO-DBMS' AND @sid IS NOT NULL;
